/// <summary>
/// The <c>AVAPriceIncreaseController</c> class is the controller class for <c>AVAPriceIncrease</c>
/// </summary>
class AVAPriceIncreaseDetectPriceDiscGroupsController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmDialogCaption("@NDX:NXAPriceIncreaseDetectPriceDiscGroup");
    this.parmClassName(classStr(AVAPriceIncreaseDetectPriceDiscGroupsService));
    this.parmMethodName(methodStr(AVAPriceIncreaseDetectPriceDiscGroupsService, runService));
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncreaseDetectPriceDiscGroupsController</c> as return value
/// </returns>
public static AVAPriceIncreaseDetectPriceDiscGroupsController newFromArgs(Args _args)
{
    AVAPriceIncreaseDetectPriceDiscGroupsController controller;

    controller = new AVAPriceIncreaseDetectPriceDiscGroupsController();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAPriceIncreaseDetectPriceDiscGroupsController controller;
    AVAPriceIncreaseDetectPriceDiscGroupsContract   dataContract;
    SysOperationStartResult                         sysOperationStartResult;

    Common                                          locCommon;
    AVAPriceIncreaseTable                           locAVAPriceIncreaseTable;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVAPriceIncreaseDetectPriceDiscGroupsController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();

    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(AVAPriceIncreaseTable))
        {
            locAVAPriceIncreaseTable = locCommon;

            dataContract.parmArgs(_args);
            dataContract.parmAVAPriceIncreaseSet(locAVAPriceIncreaseTable.PriceIncreaseSet);
        }

    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
